describe('addUsage', () => {
  const A = {inputTokens: 2, outputTokens: 1, totalTokens: 3};
  const B = {inputTokens: 7, outputTokens: 4, totalTokens: 11};

  it('sums each token field across two reported rounds', () => {
    expect(addUsage(A, B)).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps the reported side when the other round reported nothing', () => {
    expect(addUsage(undefined, B)).toEqual(B);
    expect(addUsage(A, undefined)).toEqual(A);
  });

  it('stays undefined when neither round reported', () => {
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});
EOF
